def search(txt, pat):
    n = len(txt)
    m = len(pat)
    lps = [0] * m
    j = 0

    # Build the LPS array
    for i in range(1, m):
        while (j > 0 and pat[i] != pat[j]):
            j = lps[j - 1]
        if pat[i] == pat[j]:
            j += 1
            lps[i] = j

    i = 0
    j = 0
    result = []

    # Search for occurrences of pat in txt
    while i < n:
        if pat[j] == txt[i]:
            i += 1
            j += 1
        if j == m:
            result.append(i - j + 1)
            j = lps[j - 1]
        elif i < n and pat[j] != txt[i]:
            if j != 0:
                j = lps[j - 1]
            else:
                i += 1

    return result if result else [-1]

